"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ComponentProps } from "react";

export type Motion3dTiltFlipPrimitiveProps = ComponentProps<typeof motion.div>;

export function Motion3dTiltFlipPrimitive({ children, ...props }: Motion3dTiltFlipPrimitiveProps) {
  const reduceMotion = useReducedMotion();
  return (
    <div style={{ perspective: 800 }}>
      <motion.div
        {...props}
        whileHover={reduceMotion ? undefined : { rotateY: 180, rotateX: -10.8 }}
        transition={reduceMotion ? { duration: 0.12 } : { duration: 0.28, ease: [0.23, 1, 0.32, 1] }}
        style={{ ...props.style, transformStyle: "preserve-3d" }}
      >
        {children}
      </motion.div>
    </div>
  );
}
